import sys
input = sys.stdin.read
data = input().split()

n, k = map(int, data)

if n % 2 == 1:
    print("No")
else:
    ans = []
    for i in range(k):
        ans.append(max(0, n // 2 - k + i))
    if sum([2 ** x for x in ans]) == n:
        print("Yes")
        print(*ans)
    else:
        print("No")
